import {sortedTalents} from './ui.js?v=183';
import * as E from './engine.js?v=183';
import {ACTIONS,COUNTRY,ROSTER,STAT_NAMES,TALENTS} from './data.js?v=183';
import {fullBody} from './visuals.js?v=183';
import {availability} from './presentation.js?v=183';
import {quickActionMarkup} from './quick-actions.js?v=183';
import {heading,esc,icon,button,portrait,nationalities,nationalityFlags,talentIcon} from './ui.js?v=183';
export function personnelPanel(s,selectedId){
 const agents=E.team(s),pending=s.recruitments.filter(r=>r.faction===s.player),a=agents.find(a=>a.id===selectedId)||agents[0],free=agents.filter(a=>!a.task&&a.status!=='captured').length;
 const roster=`<nav class="personnel-roster" aria-label="Choisir un agent"><div class="personnel-roster-heading"><span>VOTRE UNITÉ</span><strong>${agents.length}<small> / 4</small></strong></div>${agents.map((b,i)=>{const state=availability(b);return `<button class="personnel-member ${b.id===a?.id?'selected':''}" data-cmd="select-agent" data-id="${esc(b.id)}" aria-pressed="${b.id===a?.id}"><span class="personnel-member-number">0${i+1}</span>${portrait(b)}<span class="personnel-member-copy"><strong>${esc(b.name)}</strong><small>${esc(COUNTRY[b.country].city)}</small><span class="personnel-member-state ${state.kind}">${b.task?b.task.remaining+' tour(s) · '+(b.task.queued?'planifié':'en mission'):b.status==='captured'?'En détention':b.status==='injured'?'Blessé':'Disponible'}</span></span></button>`;}).join('')}${pending.map(r=>`<div class="personnel-pending">${icon('clock')}<strong>${esc(ROSTER.find(a=>a.id===(r.templateId||r.id))?.name||r.id)}</strong><small>Arrivée dans ${r.remaining} tour(s)</small></div>`).join('')}${agents.length+pending.length<4?button(icon('plus')+' Recruter','recruit','wide personnel-recruit'):''}</nav>`;
 if(!a)return `${heading('PERSONNEL / SIGMA','Votre unité','Aucun agent actif.',button('Recruter','recruit','primary'))}${roster}`;
 const status=availability(a),task=a.task,energy=100-a.fatigue,target=COUNTRY[task?.target]?.name||s.suspects.find(t=>t.id===task?.target)?.name||COUNTRY[a.country].name,locked=E.travelInProgress(a),detained=a.status==='captured';
 return `<section class="personnel-command">${heading('PERSONNEL / SIGMA','Votre unité',`${free} agent(s) disponible(s) · ${agents.filter(a=>a.task).length} mission(s) engagée(s)`)}<div class="personnel-workspace">${roster}<figure class="personnel-portrait-stage"><div class="personnel-image-label"><span>DOSSIER OPÉRATIONNEL</span><strong>${esc(a.name)}</strong></div>${fullBody(a)}<figcaption><span>${nationalityFlags(a)} ${esc(a.role)}</span><small>${esc(COUNTRY[a.country].name)} · ${esc(a.cover)}</small></figcaption></figure><section class="personnel-dossier" aria-label="Dossier de ${esc(a.name)}"><header class="personnel-identity"><div><span class="eyebrow">${esc(a.role)}</span><h2>${esc(a.name)}</h2></div><span class="personnel-status ${status.kind}">${icon(status.icon)}${detained?'En détention':task?'En mission':a.status==='injured'?'Blessé':'Disponible'}</span></header><p class="personnel-biography">${esc(a.bio)}</p><div class="personnel-capabilities" aria-label="Capacités">${a.stats.map((n,i)=>`<div><span>${STAT_NAMES[i]}</span><strong>${n}<small>/10</small></strong><progress max="10" value="${n}" aria-label="${STAT_NAMES[i]} : ${n} sur 10"></progress></div>`).join('')}</div><div class="personnel-condition"><div><span>Énergie <strong>${energy}<small>/100</small></strong></span><progress max="100" value="${energy}" class="${energy<30?'critical':''}" aria-label="Énergie : ${energy} sur 100"></progress></div><div><span>Exposition <strong>${a.exposure}<small>/100</small></strong></span><progress max="100" value="${Math.min(100,a.exposure)}" class="exposure ${a.exposure>=60?'critical':''}" aria-label="Exposition : ${a.exposure} sur 100"></progress></div></div><section class="personnel-mission ${task?'engaged':''}"><div class="personnel-mission-heading"><span>${detained?'AGENT CAPTURÉ':task?task.queued?'ORDRE PLANIFIÉ':'MISSION EN COURS':'PROCHAINE AFFECTATION'}</span>${task?`<strong>Fin T${s.turn+task.remaining-1}</strong>`:''}</div><h3>${detained?'Extraction nécessaire':task?esc(ACTIONS[task.type].name):'Prêt à intervenir'}</h3><p>${detained?`Détenu en ${esc(COUNTRY[a.country].name)}.`:task?esc(target)+' · '+task.remaining+' tour(s) restant(s)':esc(COUNTRY[a.country].city)+' · '+(a.weapon?'Arme équipée':'Sans arme')+' · '+(a.country===a.faction?'Au QG':E.hasSafehouse(s,a.faction,a.country)?'Planque disponible':'Sans planque')}</p>${task?`<progress max="${task.total}" value="${task.total-task.remaining}" aria-label="Progression de la mission"></progress>`:''}<div class="personnel-mission-actions">${button(icon('target')+(detained?' Consulter la détention':' Affecter une opération'),'agent','primary',`data-id="${esc(a.id)}" ${task||s.ended?'disabled title="Agent déjà en mission ou campagne terminée"':''}`)}${task?button(icon('close')+' Annuler','cancel','small',`data-id="${esc(a.id)}" ${locked||s.ended?'disabled title="Déplacement commencé ou campagne terminée"':''}`):!detained?button(icon('moon')+' Repos','agent-rest','small',`data-id="${esc(a.id)}" ${s.ended?'disabled':''}`):''}</div></section>${!task&&!detained?quickActionMarkup(s,a):''}<section class="personnel-talents"><h3>Talents</h3><div>${sortedTalents(a).map(t=>`<details><summary>${talentIcon(t)}<strong>${esc(TALENTS[t][0])}</strong>${icon('chevron')}</summary><p>${esc(TALENTS[t][1])}</p></details>`).join('')}</div></section><footer class="personnel-footer"><div>${button('Journal','agent-journal','small',`data-id="${esc(a.id)}"`)}${button('Voir le pays','map-country','small',`data-id="${a.country}"`)}</div></footer></section></div></section>`;
}
